class Solution:

def checkValidString(self, s: str) -> bool:

open_stack = []

star_stack = []

for i, char in enumerate(s):

# 将左括号添加到 open_stack，将星号添加到 star_stack

if char == "(":

open_stack.append(i)

elif char == "*":

star_stack.append(i)

# 检查当前左括号或星号是否与右括号匹配，如果匹配则弹出

# 如果没有找到匹配的括号，则表达式无效。

elif char == ")":

if open_stack:

open_stack.pop()

elif star_stack:

star_stack.pop()

else:

return False

# 检查剩余栈的长度

while open_stack and star_stack:

o = open_stack.pop()

s = star_stack.pop()

if o > s:

return False

return len(open_stack) == 0

